{"path":"/Volumes/Models/ds4/.workspaces/server-agent-day-20261004/confirmation-visible/lru/solution.py","content":"def solve(payload, config):
    capacity = config["capacity"]
    if capacity <= 0:
        return {"cache": [], "hits": 0, "misses": len(payload), "evictions": []}

    cache = []
    hits = 0
    misses = 0
    evictions = []

    for key in payload:
        found = False
        index = 0
        while index < len(cache):
            if cache[index] == key:
                found = True
                break
            index = index + 1

        if found:
            hits = hits + 1
            cache.pop(index)
            cache.append(key)
        else:
            misses = misses + 1
            cache.append(key)
            if len(cache) > capacity:
                evicted = cache.pop(0)
                evictions.append(evicted)

    return {"cache": cache, "hits": hits, "misses": misses, "evictions": evictions}
